import sys, json, base64, datetime, math

doc = json.load(sys.stdin)
# GH #1249: the recurrence pass of this memory. It runs once per dream run,
# armed by `./dream-glue` when the night has booked its receipt (phase
# `closed`), and never on a clock of its own (R-AG-1: no tick without an
# event). It reads this hive's own store -- the member's turns of the last
# `window_days` and their episode embeddings -- groups the questions that come
# back, and asks `./dreamer` to turn each routine into a prewarm candidate. The
# candidates leave the hive on the lane `recurring`; nobody answers it.
#
# Every knob is a param of this cell (GH #138): the literal beside each name is
# the shipped default, the same value the template config and
# `contract.settings` carry.
P = doc.get("params") or {}


def _knob(key, default):
    v = P.get(key, default)
    return default if v is None else v


def _int(key, default):
    v = _knob(key, default)
    if isinstance(v, str) and not v.strip():
        return default
    return int(v)


def _float(key, default):
    v = _knob(key, default)
    if isinstance(v, str) and not v.strip():
        return default
    return float(v)


def _str(key, default):
    v = _knob(key, default)
    return "" if v is None else str(v)


# How far back a routine is looked for, in days before the night.
WINDOW_DAYS = _int("window_days", 14)
# On how many distinct local days a question has to come back inside the window
# before it is a routine (four in fourteen: twice a week for two weeks).
MIN_DAYS = _int("min_days", 4)
# Two questions are the same question when the cosine of their episode vectors
# reaches this, read as the cosine of the float embeddings (the scale the brief
# and R-WP-6 speak). The store keeps the vectors binarised to their signs, and
# two sign vectors of float vectors at angle theta differ in theta / pi of their
# bits on average (random-hyperplane estimate). So the grouping compares the
# sign vectors' own cosine, 1 - 2 * hamming / bits, against
# SIGN_COSINE_MIN = 1 - 2 * acos(cosine_min) / pi (0.82 -> about 0.61). Applied
# to the sign vectors unconverted, 0.82 would ask for a float cosine of about
# 0.96, and a question asked again in other words would not group.
COSINE_MIN = _float("cosine_min", 0.82)
SIGN_COSINE_MIN = 1.0 - 2.0 * math.acos(min(1.0, max(-1.0, COSINE_MIN))) / math.pi
# The time of day a routine keeps: every occurrence within this many minutes of
# the routine's time, either side.
TOLERANCE_MIN = _int("tolerance_min", 30)
# The member's time zone (IANA name). Times of day and weekdays are read in it,
# and every candidate carries it beside its rrule. An unknown name reads as UTC
# and says so on stderr.
TZ = _str("tz", "UTC")
# Page bound of the two reads (episodes, embeddings). Both read newest first,
# so a full page leaves out the window's oldest turns, not its latest; a full
# page is said on stderr.
EPISODE_ROWS = _int("episode_rows", 2000)
# Routines one night puts to the dreamer, most frequent first.
MAX_ROUTINES = _int("max_routines", 12)
# Spellings of a routine's question a candidate carries as `triggers`.
MAX_TRIGGERS = _int("max_triggers", 16)

WEEKDAYS = ("MO", "TU", "WE", "TH", "FR", "SA", "SU")


def park():
    sys.stdout.write(json.dumps([]))
    sys.exit(0)


def emit(msgs):
    sys.stdout.write(json.dumps(msgs))
    sys.exit(0)


def zone(name):
    """The zone a routine is read in; UTC when the name is unknown."""
    if not name or name == "UTC":
        return datetime.timezone.utc
    try:
        import zoneinfo
        return zoneinfo.ZoneInfo(name)
    except Exception:
        sys.stderr.write("recur: unknown tz %r, read as UTC\n" % name)
        return datetime.timezone.utc


def parse_at(value):
    """An ISO-8601 instant as an aware datetime, or None."""
    try:
        at = datetime.datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    except Exception:
        return None
    if at.tzinfo is None:
        at = at.replace(tzinfo=datetime.timezone.utc)
    return at


def bits_of(blob):
    """A stored vector (strict base64 text, the store's `similar` format) as bytes."""
    try:
        return base64.b64decode(str(blob or ""), validate=True)
    except Exception:
        return b""


def sign_vector(vec):
    """A binarised vector (bytes) as (int, bits): its hamming distance to
    another is then one xor and one popcount, not a loop over its bytes."""
    return int.from_bytes(vec, "big"), 8 * len(vec)


def cosine(a, b):
    """Cosine of two sign vectors given as (int, bits): 1 - 2 * hamming / bits.
    Vectors of different length (two embedding generations) or empty ones are
    unrelated."""
    if not a[1] or a[1] != b[1]:
        return 0.0
    return 1.0 - 2.0 * (a[0] ^ b[0]).bit_count() / a[1]


def audience_key(raw):
    """The canonical spelling of an episode's audience set, or '' when it has none."""
    try:
        members = json.loads(raw) if isinstance(raw, str) else raw
    except Exception:
        return ""
    if not isinstance(members, list) or not members:
        return ""
    return json.dumps(sorted(str(m) for m in members))


def group_questions(items):
    """Greedy, deterministic grouping in time order: a question joins the group
    whose first question is nearest to it (sign cosine >= SIGN_COSINE_MIN, the
    sign-bit reading of cosine_min) and was asked in the same audience;
    otherwise it opens a group. `items` carry `id`, `vec`
    (bytes), `at` (datetime), `aud` (audience key) and `text`."""
    groups = []
    for it in sorted(items, key=lambda x: (x["at"], x["id"])):
        vec = sign_vector(it["vec"])
        best, best_cos = None, SIGN_COSINE_MIN
        for g in groups:
            if g["aud"] != it["aud"]:
                continue
            c = cosine(g["seed"], vec)
            if c >= best_cos and (best is None or c > best_cos):
                best, best_cos = g, c
        if best is None:
            groups.append({"seed": vec, "aud": it["aud"], "items": [it]})
        else:
            best["items"].append(it)
    return groups


def minute_distance(a, b):
    d = abs(a - b) % 1440
    return min(d, 1440 - d)


def time_profile(items, tz):
    """The routine inside one group: the time of day most occurrences keep
    (within +-TOLERANCE_MIN), the occurrences that keep it, their distinct local
    days and weekdays. Ties go to the earlier time."""
    local = [(it, it["at"].astimezone(tz)) for it in items]
    best = None
    for _, lt in local:
        centre = lt.hour * 60 + lt.minute
        kept = [(it, t) for it, t in local
                if minute_distance(t.hour * 60 + t.minute, centre) <= TOLERANCE_MIN]
        days = len({t.date() for _, t in kept})
        key = (-days, centre)
        if best is None or key < best[0]:
            best = (key, kept)
    kept = best[1] if best else []
    minutes = sorted(t.hour * 60 + t.minute for _, t in kept)
    at_min = minutes[(len(minutes) - 1) // 2] if minutes else 0
    return {"kept": [it for it, _ in kept], "at_min": at_min,
            "days": len({t.date() for _, t in kept}),
            "weekdays": sorted({t.weekday() for _, t in kept})}


def rrule_of(at_min, weekdays):
    """The routine as an RFC 5545 rule: DAILY when every weekday is in it."""
    time = "BYHOUR=%d;BYMINUTE=%d" % (at_min // 60, at_min % 60)
    if len(weekdays) == 7:
        return "FREQ=DAILY;" + time
    return "FREQ=WEEKLY;BYDAY=%s;%s" % (",".join(WEEKDAYS[w] for w in weekdays), time)


def find_routines(items, night, tz_name):
    """The routines of one window: groups of the same question, asked on at
    least MIN_DAYS distinct local days of the WINDOW_DAYS before `night`, at one
    time of day. Most frequent first, at most MAX_ROUTINES."""
    tz = zone(tz_name)
    end = parse_at(night)
    if end is None:
        return []
    start = end - datetime.timedelta(days=WINDOW_DAYS)
    inside = [it for it in items if start <= it["at"] <= end and it["vec"] and it["aud"]]
    found = []
    for g in group_questions(inside):
        prof = time_profile(g["items"], tz)
        if prof["days"] < MIN_DAYS:
            continue
        triggers = []
        for it in prof["kept"]:
            t = " ".join(str(it["text"] or "").split())
            if t and t not in triggers:
                triggers.append(t)
        found.append({"rrule": rrule_of(prof["at_min"], prof["weekdays"]),
                      "tz": tz_name or "UTC", "days": prof["days"],
                      "audience_set": json.loads(g["aud"]),
                      "triggers": triggers[:MAX_TRIGGERS],
                      "episode_ids": [it["id"] for it in prof["kept"]],
                      "at_min": prof["at_min"]})
    found.sort(key=lambda r: (-r["days"], r["at_min"], r["episode_ids"][0]))
    for i, r in enumerate(found[:MAX_ROUTINES]):
        r["group"] = "g%d" % (i + 1)
    return found[:MAX_ROUTINES]


def items_of(episodes, embeddings):
    """Join the two reads: one item per episode that has a ready vector of the
    embedding generation most of the window's vectors belong to."""
    by_model = {}
    for e in embeddings:
        by_model.setdefault(str(e.get("model_id") or ""), {})[str(e.get("owner_id"))] = e
    if not by_model:
        return []
    model = sorted(by_model, key=lambda m: (len(by_model[m]), m))[-1]
    vecs = by_model[model]
    items = []
    for ep in episodes:
        at = parse_at(ep.get("happened_at"))
        vec = bits_of((vecs.get(str(ep.get("id"))) or {}).get("blob"))
        if at is None or not vec:
            continue
        items.append({"id": str(ep.get("id")), "vec": vec, "at": at,
                      "aud": audience_key(ep.get("audience_set")),
                      "text": ep.get("content") or ""})
    return items


def parse_model_json(text):
    """A model answer that may be fenced or wrapped in a sentence."""
    s = str(text or "").strip()
    if s.startswith("```"):
        s = s.strip("`")
        if s.lower().startswith("json"):
            s = s[4:]
    try:
        return json.loads(s)
    except Exception:
        pass
    a, b = s.find("{"), s.rfind("}")
    if a >= 0 and b > a:
        try:
            return json.loads(s[a:b + 1])
        except Exception:
            return None
    return None


def as_int(value):
    """A whole number the model gave, or None (a bool is not a number)."""
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, float) and value == int(value):
        return int(value)
    if isinstance(value, str) and value.strip().isdigit():
        return int(value.strip())
    return None


def candidates_of(routines, answer):
    """The dreamer's candidates, joined to the routines they name. R-WP-6: the
    freshness of a routine is the dreamer's call, so `ttl_min` is required on
    every candidate and has no default -- a candidate without a positive
    `ttl_min`, or with `tool: none`, is no prewarm and is left out. Returns
    {audience key: [candidate]}."""
    by_group = {r.get("group"): r for r in routines}
    out = {}
    listed = answer.get("candidates") if isinstance(answer, dict) else None
    for c in listed if isinstance(listed, list) else []:
        if not isinstance(c, dict):
            continue
        r = by_group.get(c.get("group"))
        tool = str(c.get("tool") or "").strip()
        ttl = as_int(c.get("ttl_min"))
        lead = as_int(c.get("lead_min"))
        topic = str(c.get("topic") or "").strip()
        query = str(c.get("query") or "").strip()
        if r is None or not tool or tool.lower() == "none" or ttl is None or ttl <= 0:
            continue
        if not topic or not query:
            continue
        cand = {"topic": topic, "query": query, "tool": tool,
                "triggers": r.get("triggers", []), "rrule": r.get("rrule"),
                "tz": r.get("tz"), "lead_min": max(lead or 0, 0), "ttl_min": ttl,
                "evidence": {"episode_ids": r.get("episode_ids", []),
                             "days": r.get("days"), "window_days": WINDOW_DAYS}}
        out.setdefault(json.dumps(r.get("audience_set") or []), []).append(cand)
    return out


INSTRUCTIONS = (
    "You turn the recurring questions of one member into prewarm candidates: an answer "
    "fetched shortly before the member usually asks. Answer with JSON only, shape: "
    "{\"candidates\":[{\"group\":\"g1\",\"topic\":\"\",\"query\":\"\",\"tool\":\"\","
    "\"lead_min\":0,\"ttl_min\":0}]}.\n\n"
    "You receive routines: each one is a question that came back on several days at about "
    "the same time (`rrule`, in the time zone `tz`), with the words the member used. For "
    "each routine decide:\n"
    "- `topic`: a short name of what the member wants to know.\n"
    "- `query`: the one question to fetch ahead, phrased so a tool can answer it.\n"
    "- `tool`: the kind of tool whose fresh result answers it (for example weather, news, "
    "calendar, web search), or \"none\" when nothing fetched ahead would help -- a "
    "question about the member's own memory, a feeling, a chat.\n"
    "- `lead_min`: how many minutes before the routine's time to fetch.\n"
    "- `ttl_min`: how many minutes a fetched answer stays fresh for THIS routine. You "
    "decide it per routine; there is no default, and a candidate without it is dropped.\n\n"
    "Leave a routine out rather than guess. Never invent a group.")


def store_op(ops, ph):
    """One store message: a bundle when it carries more than one op."""
    return {"header": {"route": "rstore", "phase": ph, "dream_run": run_id,
                       "dream_to": night},
            "messages": [{"origin": "assistant", "type": "tool_call",
                          "id": "r-%s-%d" % (ph, i), "text": json.dumps(o)}
                         for i, o in enumerate(ops)]}


def texts(body):
    """The tool_result texts of a store answer, in call order."""
    return [m.get("text") or "" for m in body.get("messages", [])
            if m.get("type") in ("tool_result", "text")]


def rows(text):
    try:
        v = json.loads(text or "[]")
    except Exception:
        return []
    return v if isinstance(v, list) else []


body = doc.get("body") or {}
h = (doc.get("envelope") or {}).get("header", {})
ctx = h.get("context", {})
hop = h.get("hop", {})
phase = str(ctx.get("mem_phase", ""))
op = hop.get("operation")
err = str(hop.get("error_code", "") or "")
run_id = str(ctx.get("dream_run", ""))
night = str(ctx.get("dream_to", ""))

if (err and op) or int(hop.get("bundle_errors") or 0) > 0:
    sys.stderr.write("recur: the store refused phase %r (%s): no candidates tonight\n"
                     % (phase, err or "bundle_errors"))
    park()

if not run_id or not night:
    park()

if phase == "recur-arm":
    end = parse_at(night)
    if end is None:
        park()
    start = (end - datetime.timedelta(days=WINDOW_DAYS)).isoformat().replace("+00:00", "Z")
    emit([store_op([
        {"operation": "select", "table": "episodes",
         "columns": ["id", "content", "happened_at", "audience_set"],
         "where": {"sender": "user", "happened_at": {"gte": start},
                   "muted_at": {"is_null": True}, "closed_at": {"is_null": True}},
         "order_by": [{"col": "happened_at", "dir": "desc"}],
         "limit": EPISODE_ROWS},
        {"operation": "select", "table": "embeddings",
         "columns": ["owner_id", "model_id", "blob"],
         "where": {"owner_table": "episodes", "status": "ready",
                   "created_at": {"gte": start}},
         "order_by": [{"col": "created_at", "dir": "desc"}],
         "limit": EPISODE_ROWS},
    ], "recur-read")])

if phase == "recur-read":
    parts = texts(body)
    if len(parts) < 2:
        park()
    episodes, embeddings = rows(parts[0]), rows(parts[1])
    for name, page in (("episodes", episodes), ("embeddings", embeddings)):
        if len(page) >= EPISODE_ROWS:
            sys.stderr.write("recur: the %s read is a full page (%d)\n" % (name, EPISODE_ROWS))
    routines = find_routines(items_of(episodes, embeddings), night, TZ)
    if not routines:
        park()
    ask = [{"group": r["group"], "questions": r["triggers"], "rrule": r["rrule"],
            "tz": r["tz"], "days": r["days"]} for r in routines]
    emit([store_op([{"operation": "insert", "table": "scratch",
                     "row": {"key": run_id, "kind": "recur-routines", "created_at": night,
                             "payload": json.dumps(routines, sort_keys=True)}}],
                   "recur-parked"),
          {"header": {"route": "recur-ask", "phase": "recur-ask", "dream_run": run_id,
                      "dream_to": night},
           "system": {"instructions": {"text": INSTRUCTIONS}},
           "messages": [{"origin": "user", "type": "text",
                         "text": json.dumps({"night": night, "routines": ask})}]}])

if phase == "recur-said":
    if hop.get("finish_reason") == "error":
        sys.stderr.write("recur: dreamer error, no candidates tonight\n")
        park()
    answer = None
    for m in body.get("messages", []):
        if m.get("type") == "text" and m.get("text"):
            answer = parse_model_json(m.get("text"))
            break
    if not isinstance(answer, dict):
        sys.stderr.write("recur: the dreamer's answer is not JSON, no candidates tonight\n")
        park()
    emit([store_op([{"operation": "insert", "table": "scratch",
                     "row": {"key": run_id, "kind": "recur-answer", "created_at": night,
                             "payload": json.dumps(answer, sort_keys=True)}}],
                   "recur-answered")])

if phase == "recur-answered" and op == "insert":
    emit([store_op([{"operation": "select", "table": "scratch",
                     "columns": ["kind", "payload"],
                     "where": {"key": run_id,
                               "kind": {"in": ["recur-routines", "recur-answer"]}}}],
                   "recur-merge")])

if phase == "recur-merge":
    parked = {}
    for r in rows((texts(body) or [""])[0]):
        payload = r.get("payload")
        try:
            parked[r.get("kind")] = json.loads(payload) if isinstance(payload, str) else payload
        except Exception:
            park()
    routines = parked.get("recur-routines")
    if not isinstance(routines, list):
        park()
    out = candidates_of(routines, parked.get("recur-answer"))
    if not out:
        park()
    emit([{"header": {"route": "recurring", "phase": "recurring", "dream_run": run_id,
                      "dream_to": night},
           "messages": [{"origin": "assistant", "type": "text",
                         "text": json.dumps({"candidates": cands,
                                             "audience_set": json.loads(aud)},
                                            sort_keys=True)}]}
          for aud, cands in sorted(out.items())])

park()
